namespace Endjin.Badger
{
    using System.Text;

    /// <summary>
    /// A table of one font's advance widths and kerning, in font units, generated by
    /// <c>tools/GenerateFontMetrics.cs</c>. <see cref="FontMetrics{TTable}"/> measures text with it.
    /// </summary>
    /// <remarks>
    /// The members are static so that each table is a struct whose spans point straight at data compiled
    /// into the assembly; <see cref="FontMetrics{TTable}"/> is specialised for each table, so measuring
    /// allocates nothing and costs no more than if the algorithm were written against one table.
    /// </remarks>
    internal interface IFontMetricsTable
    {
        /// <summary>Gets the font units per em.</summary>
        static abstract int UnitsPerEm { get; }

        /// <summary>Gets the advance, in font units, of a character the tables do not cover.</summary>
        static abstract int FallbackAdvanceUnits { get; }

        /// <summary>
        /// Gets the advances for <see cref="FontMetrics.LatinFirst"/> to <see cref="FontMetrics.LatinLast"/>,
        /// indexed by code point - <see cref="FontMetrics.LatinFirst"/> (0 = not in the font).
        /// </summary>
        static abstract ReadOnlySpan<ushort> LatinAdvances { get; }

        /// <summary>Gets the code points outside the Latin range that the font covers, in ascending order.</summary>
        static abstract ReadOnlySpan<int> ExtraCodePoints { get; }

        /// <summary>Gets the advance of each code point in <see cref="ExtraCodePoints"/>.</summary>
        static abstract ReadOnlySpan<ushort> ExtraAdvances { get; }

        /// <summary>Gets the kerning pairs between Latin characters, keyed by (left &lt;&lt; 16) | right, in ascending order.</summary>
        static abstract ReadOnlySpan<int> KerningPairs { get; }

        /// <summary>Gets the kerning of each pair in <see cref="KerningPairs"/>.</summary>
        static abstract ReadOnlySpan<short> KerningUnits { get; }
    }

    /// <summary>
    /// The rules shared by every <see cref="IFontMetricsTable"/>.
    /// </summary>
    internal static class FontMetrics
    {
        /// <summary>The first code point of the range each table holds an advance for.</summary>
        internal const int LatinFirst = 0x0020;

        /// <summary>The last code point of the range each table holds an advance for.</summary>
        internal const int LatinLast = 0x024F;

        /// <summary>
        /// Determines whether a character is left out of the width when it ends the text. This is
        /// breaking whitespace, which SixLabors.Fonts lets hang past the end of the line.
        /// </summary>
        /// <param name="codePoint">The Unicode code point.</param>
        /// <returns>True if the character is ignored at the end of a text.</returns>
        internal static bool IsTrailingSpaceIgnored(int codePoint) =>
            Rune.IsWhiteSpace(new Rune(codePoint)) && codePoint != 0x00A0;

        /// <summary>
        /// Determines whether a character is a combining diacritical mark (U+0300 to U+036F), which takes no width.
        /// </summary>
        /// <param name="codePoint">The Unicode code point.</param>
        /// <returns>True if the character is a combining mark.</returns>
        internal static bool IsCombiningMark(int codePoint) => codePoint is >= 0x0300 and <= 0x036F;
    }

    /// <summary>
    /// Measures text with a table of a font's advances and kerning, the way SixLabors.Fonts measured it
    /// with the font itself: advances are summed in font units, kerning between adjacent Latin characters
    /// is added, and breaking whitespace at the end of the text is ignored.
    /// </summary>
    /// <typeparam name="TTable">The font's table.</typeparam>
    /// <remarks>
    /// Combining diacritical marks (U+0300 to U+036F) take no width. Any other character the table does
    /// not cover is given <see cref="IFontMetricsTable.FallbackAdvanceUnits"/>.
    /// </remarks>
    internal static class FontMetrics<TTable>
        where TTable : struct, IFontMetricsTable
    {
        /// <summary>
        /// Measures the advance width of a text, in font units.
        /// </summary>
        /// <param name="text">The text, as it will be displayed (i.e., already HTML-decoded).</param>
        /// <returns>The width in font units.</returns>
        internal static int MeasureUnits(ReadOnlySpan<char> text)
        {
            ReadOnlySpan<char> measured = TrimIgnoredTrailingSpace(text);
            if (measured.IsEmpty && !text.IsEmpty)
            {
                // A text made only of whitespace is measured as its first character, as SixLabors.Fonts does.
                Rune.DecodeFromUtf16(text, out Rune first, out _);
                return AdvanceUnits(first.Value);
            }

            int units = 0;
            int previous = -1;
            foreach (Rune rune in measured.EnumerateRunes())
            {
                int codePoint = rune.Value;
                if (FontMetrics.IsCombiningMark(codePoint))
                {
                    continue;
                }

                units += AdvanceUnits(codePoint);
                if (previous >= 0)
                {
                    units += KerningUnitsFor(previous, codePoint);
                }

                previous = codePoint;
            }

            return units;
        }

        /// <summary>
        /// Measures the advance width of a text, in pixels.
        /// </summary>
        /// <param name="text">The text, as it will be displayed (i.e., already HTML-decoded).</param>
        /// <param name="pixelSize">The font size in pixels.</param>
        /// <returns>The width in pixels.</returns>
        /// <remarks>
        /// The total is scaled to pixels once. When the font size divided by the units per em is exact in
        /// binary (as 11/2048 is), the width has no rounding error as long as the total stays below
        /// 2^24 / font size units.
        /// </remarks>
        internal static float MeasureWidth(ReadOnlySpan<char> text, float pixelSize) =>
            MeasureUnits(text) * (pixelSize / TTable.UnitsPerEm);

        /// <summary>
        /// Gets the advance of a single character, in font units.
        /// </summary>
        /// <param name="codePoint">The Unicode code point.</param>
        /// <returns>The advance in font units.</returns>
        internal static int AdvanceUnits(int codePoint)
        {
            if (codePoint is >= FontMetrics.LatinFirst and <= FontMetrics.LatinLast)
            {
                int advance = TTable.LatinAdvances[codePoint - FontMetrics.LatinFirst];
                return advance != 0 ? advance : TTable.FallbackAdvanceUnits;
            }

            int index = TTable.ExtraCodePoints.BinarySearch(codePoint);
            return index >= 0 ? TTable.ExtraAdvances[index] : TTable.FallbackAdvanceUnits;
        }

        private static int KerningUnitsFor(int left, int right)
        {
            if (left > FontMetrics.LatinLast || right > FontMetrics.LatinLast)
            {
                return 0;
            }

            int index = TTable.KerningPairs.BinarySearch((left << 16) | right);
            return index >= 0 ? TTable.KerningUnits[index] : 0;
        }

        private static ReadOnlySpan<char> TrimIgnoredTrailingSpace(ReadOnlySpan<char> text)
        {
            while (!text.IsEmpty)
            {
                // Every character IsTrailingSpaceIgnored accepts is in the Basic Multilingual Plane.
                char last = text[^1];
                if (char.IsSurrogate(last) || !FontMetrics.IsTrailingSpaceIgnored(last))
                {
                    break;
                }

                text = text[..^1];
            }

            return text;
        }
    }
}
